fn node(w: &[u64], text: &[u8], i: usize) -> Result<(Value, usize), Error> {
    if i + TAPE_NODE_WORDS > w.len() { return Err(Error::Internal); }
    let (head, aux) = (w[i], w[i + 1]);
    let (kind, n) = (head & TAPE_KIND_MASK, head >> TAPE_LEN_SHIFT);
    let mut i = i + TAPE_NODE_WORDS;
    match kind {
        VBM_JSON_NULL => Ok((Value::Null, i)),
        VBM_JSON_FALSE => Ok((Value::Bool(false), i)),
        VBM_JSON_TRUE => Ok((Value::Bool(true), i)),
        VBM_JSON_NUMBER | VBM_JSON_STRING => {
            let (a, n) = (aux as usize, n as usize);
            if a.checked_add(n).map_or(true, |e| e > text.len()) { return Err(Error::Internal); }
            let s = std::str::from_utf8(&text[a..a + n]).map_err(|_| Error::Internal)?.to_string();
            Ok((if kind == VBM_JSON_NUMBER { Value::Number(s) } else { Value::String(s) }, i))
        }
        VBM_JSON_ARRAY | VBM_JSON_OBJECT => {
            let aux = aux as usize;
            if aux < TAPE_NODE_WORDS || aux > w.len() - (i - TAPE_NODE_WORDS) { return Err(Error::Internal); }
            let end = i - TAPE_NODE_WORDS + aux;
            let mut items = Vec::new();
            let mut members = Vec::new();
            for _ in 0..n {
                if kind == VBM_JSON_ARRAY {
                    let (v, j) = node(w, text, i)?;
                    items.push(v);
                    i = j;
                } else {
                    if i + TAPE_NODE_WORDS > w.len() || w[i] & TAPE_KIND_MASK != VBM_JSON_STRING { return Err(Error::Internal); }
                    let (k, j) = node(w, text, i)?;
                    let (v, j) = node(w, text, j)?;
                    let k = match k { Value::String(s) => s, _ => return Err(Error::Internal) };
                    members.push((k, v));
                    i = j;
                }
            }
            if i != end { return Err(Error::Internal); }
            Ok((if kind == VBM_JSON_ARRAY { Value::Array(items) } else { Value::Object(members) }, i))
        }
        _ => Err(Error::Internal),
    }
}
